package code;

import java.util.*;

class LiquidTank {
    private double maxLevel;
    private double minLevel;
    private double currentLevel;
    private List<String> levelLog;

    public LiquidTank(double maxLevel, double minLevel, double initialLevel) {
        this.maxLevel = maxLevel;
        this.minLevel = minLevel;
        this.currentLevel = initialLevel;
        this.levelLog = new ArrayList<>();
    }

    public void updateLevel(double changeAmount) {
        currentLevel += changeAmount;

        String message = String.format("Current Level: %.1f liters", currentLevel);
        if (currentLevel > maxLevel) {
            message += " | WARNING: Overflow Risk!";
        } else if (currentLevel < minLevel) {
            message += " | ALERT: Low Level! Refill Recommended.";
        }

        System.out.println(message);
        levelLog.add(message);
    }

    public void printLevelLog() {
        System.out.println("\nLiquid Level Log:");
        for (String log : levelLog) {
            System.out.println(log);
        }
    }
}

